const NAVY = '#1d2b53';
const FROST = '#e3ecff';
const SKY = '#9cc3f5';
const GOLD = '#ffd23c';
const DEEP_GOLD = '#e8a400';
const SPARK = 'M12 2l2.2 7.8L22 12l-7.8 2.2L12 22l-2.2-7.8L2 12l7.8-2.2z';
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
// Days that earn a medal; after a year, every year does.
const MEDALS = [1, 7, 14, 30, 60, 90, 180, 365];

// Clockwise when `hole`, so inside a counterclockwise shape it cuts a hole under the nonzero rule.
function ellipse(cx, cy, rx, ry, hole) {
  const arc = 'A' + rx + ' ' + ry + ' 0 1 ' + (hole ? 1 : 0) + ' ';
  return 'M' + (cx - rx) + ' ' + cy + arc + (cx + rx) + ' ' + cy + arc + (cx - rx) + ' ' + cy + 'Z';
}

// The medal's ring and star are cut out of its disc. In full color the cuts show a deeper gold disc drawn in the
// backdrop under it; in tinted and clear mode, which remove the backdrop, they still show.
const STAR = 'M22 30.5l2.3 4.8 5.2.6-3.9 3.6 1.1 5.1-4.7-2.7-4.7 2.7 1.1-5.1-3.9-3.6 5.2-.6z';
const DISC = ellipse(22, 38, 17, 17) + ellipse(22, 38, 12.5, 12.5, true) + ellipse(22, 38, 10.5, 10.5) + STAR;

function medal(u, under) {
  const part = (d, fill) => ({ type: 'path', d, viewBox: [0, 0, 44, 58], fill });
  return { type: 'zstack', padding: { trailing: 10 * u, bottom: 8 * u },
    frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'bottomTrailing' },
    children: [
      { type: 'zstack', frame: { width: 46 * u, height: 46 * u * 58 / 44 }, children: under
        ? [part(ellipse(22, 38, 14, 14), DEEP_GOLD)]
        : [part('M8 2h11l6 18h-11z', '#ff6b5c'), part('M36 2H25l-6 18h11z', SKY), part(DISC, GOLD)] },
    ] };
}

function nextMedal(days) {
  return MEDALS.find((m) => m > days) || (Math.floor(days / 365) + 1) * 365;
}

function render(ctx) {
  // Sizes are in the prototype's units: a widget is 170 of them tall. Bricolage's line is 1.2 times its size, so
  // the gaps around the count are 0.1 of its size shorter than the prototype's.
  const u = ctx.height / 170;
  const start = ctx.data.start;
  const since = start && (start.since || start.day);
  const days = since ? Math.max(0, Math.round((new Date(ctx.today.date) - new Date(since)) / 86400000)) : 0;
  const date = since && MONTHS[Number(since.slice(5, 7)) - 1] + ' ' + Number(since.slice(8, 10));
  const line = (value) => ({ type: 'text', value, size: 12.5 * u, weight: 'semibold', color: FROST, opacity: 0.8,
    lineLimit: 1, minScale: 0.8 });

  return {
    type: 'zstack', align: 'topLeading',
    frame: { maxWidth: 'infinity', maxHeight: 'infinity' },
    widgetBackground: { type: 'zstack', frame: { maxWidth: 'infinity', maxHeight: 'infinity' }, background: NAVY,
      children: [medal(u, true)] },
    children: [
      medal(u, false),
      { type: 'button', action: 'start', rowId: start ? start.id : null,
        label: since ? 'Alcohol-free, ' + (days === 1 ? '1 day' : days + ' days') + ' since ' + date + ', next medal '
          + nextMedal(days) + ', change the day you started' : 'Alcohol-free, set the day you started',
        children: [
        { type: 'vstack', align: 'leading', spacing: 0,
          padding: { top: 15 * u, leading: 16 * u, trailing: 16 * u },
          frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topLeading' },
          children: [
            { type: 'hstack', spacing: 5 * u, frame: { height: 16 * u }, children: [
              { type: 'path', d: SPARK, viewBox: [0, 0, 24, 24], fill: SKY, frame: { width: 15 * u, height: 15 * u } },
              { type: 'text', value: 'Alcohol-free', size: 13 * u, weight: 'bold', color: SKY, lineLimit: 1 } ] },
            { type: 'text', value: !since ? 'Day one' : days === 1 ? '1 day' : days + ' days',
              fontName: 'Bricolage Grotesque Display', size: 36 * u, kerning: -1.08 * u, color: FROST, accent: true,
              lineLimit: 1, minScale: 0.5, padding: { top: 4.4 * u } },
            { type: 'vstack', align: 'leading', spacing: 0, padding: { top: 1.4 * u },
              frame: { maxWidth: ctx.width - 80 * u, alignment: 'leading' },
              children: since ? [line('since ' + date), line('next medal: ' + nextMedal(days))]
                : [line('tap to set the day'), line('you started')] },
          ] } ] },
    ],
  };
}
